// Package grpc contains the inbound ConnectRPC adapter for the soil-service.
// NOTE: proto types are generated by buf generate.
package grpc

import (
	"context"

	"connectrpc.com/connect"
	"p9e.in/samavaya/packages/errors"
	"p9e.in/samavaya/packages/p9context"
	"p9e.in/samavaya/packages/p9log"

	// Generated by buf generate
	pb "p9e.in/samavaya/agriculture/soil-service/api/v1"
	"p9e.in/samavaya/agriculture/soil-service/api/v1/soilv1connect"
	"p9e.in/samavaya/agriculture/soil-service/internal/domain"
	"p9e.in/samavaya/agriculture/soil-service/internal/ports/inbound"
)

// SoilHandler is the ConnectRPC inbound adapter.
type SoilHandler struct {
	soilv1connect.UnimplementedSoilServiceHandler
	svc inbound.SoilService
	log *p9log.Helper
}

// NewSoilHandler creates a new ConnectRPC soil handler.
func NewSoilHandler(svc inbound.SoilService, log p9log.Logger) *SoilHandler {
	return &SoilHandler{
		svc: svc,
		log: p9log.NewHelper(p9log.With(log, "component", "SoilHandler")),
	}
}

// CreateSoilSample handles creation requests.
func (h *SoilHandler) CreateSoilSample(ctx context.Context, req *connect.Request[pb.CreateSoilSampleRequest]) (*connect.Response[pb.CreateSoilSampleResponse], error) {
	h.log.Infow("msg", "CreateSoilSample request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetFieldId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "field_id is required")
	}
	entity := &domain.Soil{Name: req.Msg.GetFieldId()}
	created, err := h.svc.CreateSoil(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.CreateSoilSampleResponse{Sample: soilToProto(created)}), nil
}

// GetSoilSample handles get requests.
func (h *SoilHandler) GetSoilSample(ctx context.Context, req *connect.Request[pb.GetSoilSampleRequest]) (*connect.Response[pb.GetSoilSampleResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity, err := h.svc.GetSoil(ctx, req.Msg.GetId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.GetSoilSampleResponse{Sample: soilToProto(entity)}), nil
}

// ListSoilSamples handles list requests.
func (h *SoilHandler) ListSoilSamples(ctx context.Context, req *connect.Request[pb.ListSoilSamplesRequest]) (*connect.Response[pb.ListSoilSamplesResponse], error) {
	params := domain.ListSoilParams{PageSize: req.Msg.GetPageSize()}
	entities, total, err := h.svc.ListSoils(ctx, params)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	protos := make([]*pb.SoilSample, 0, len(entities))
	for i := range entities {
		protos = append(protos, soilToProto(&entities[i]))
	}
	return connect.NewResponse(&pb.ListSoilSamplesResponse{Samples: protos, TotalCount: total}), nil
}

func soilToProto(e *domain.Soil) *pb.SoilSample {
	return &pb.SoilSample{
		Id:       e.UUID,
		TenantId: e.TenantID,
	}
}
